 buildConfigField "String", "DROPBOX_APP_SECRET", "\"${localProps['DROPBOX_APP_SECRET'] ?: ''}\""
 }
 // ...rest of build.gradle...
}
```

**This fixes the error and is the Gradle-approved way for accessing local.properties values!**

