;\n }\n \n /**\n * Send delivery confirmation email with secure credential handling\n */\n public boolean sendDeliveryEmail(Delivery delivery) {\n try {\n // Get secure credentials\n String username = securityManager.getEmailUsername();\n String password = securityManager.getEmailPassword();\n \n if (password == null || password.isEmpty()) {\n Log.e(TAG, \"Email password not configured - cannot send email\");\n return false;\n }\n \n String recipient = securityManager.getAppEmail();\n if (recipient == null || recipient.isEmpty()) {\n Log.e(TAG, \"Recipient email not configured - cannot send email\");\n return false;\n }\n \n String subject = \"Proof of Delivery for Order: \" + delivery.getTripId();\n \n // Setup email properties with security\n Properties properties = createSecureMailProperties();\n \n // Create authenticated session\n Session session = Session.getInstance(properties, new Authenticator() {\n @Override\n protected PasswordAuthentication getPasswordAuthentication() {\n return new PasswordAuthentication(username, password);\n }\n });\n \n // Create message\n MimeMessage message = new MimeMessage(session);\n message.setFrom(new InternetAddress(username));\n message.addRecipient(MimeMessage.RecipientType.TO, new InternetAddress(recipient));\n message.setSubject(subject);\n \n // Create multipart content\n Multipart multipart = new MimeMultipart();\n \n // Add text body\n MimeBodyPart textBodyPart = new MimeBodyPart();\n textBodyPart.setText(createEmailBody(delivery));\n multipart.addBodyPart(textBodyPart);\n \n // Generate and attach PDF\n File pdfFile = generatePODPdf(delivery);\n if (pdfFile != null && pdfFile.exists()) {\n addAttachment(multipart, pdfFile.getAbsolutePath(), \"POD_\" + delivery.getDocument() + \".pdf\");\n }\n \n message.setContent(multipart);\n \n // Send email\n Transport.send(message);\n \n // Clean up temporary files\n if (pdfFile != null && pdfFile.exists()) {\n pdfFile.delete();\n }\n \n Log.d(TAG, \"Email sent successfully for document: \" + delivery.getDocument());\n return true;\n \n } catch (Exception e) {\n Log.e(TAG, \"Failed to send email: \" + e.getMessage(), e);\n return false;\n }\n }\n \n /**\n * Create secure mail properties\n */\n private Properties createSecureMailProperties() {\n Properties properties = new Properties();\n \n // Gmail SMTP configuration with security\n properties.put(\"mail.smtp.host\", \"smtp.gmail.com\");\n properties.put(\"mail.smtp.port\", \"587\");\n properties.put(\"mail.smtp.auth\", \"true\");\n properties.put(\"mail.smtp.starttls.enable\", \"true\");\n properties.put(\"mail.smtp.starttls.required\", \"true\");\n \n // Additional security properties\n properties.put(\"mail.smtp.ssl.protocols\", \"TLSv1.2 TLSv1.3\");\n properties.put(\"mail.smtp.ssl.ciphersuites\", \n \"TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256,\" +\n \"TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,\" +\n \"TLS_DHE_RSA_WITH_AES_128_GCM_SHA256,\" +\n \"TLS_DHE_RSA_WITH_AES_256_GCM_SHA384\");\n properties.put(\"mail.smtp.ssl.checkserveridentity\", \"true\");\n \n // Connection timeout and security\n properties.put(\"mail.smtp.connectiontimeout\", \"30000\");\n properties.put(\"mail.smtp.timeout\", \"30000\");\n properties.put(\"mail.smtp.writetimeout\", \"30000\");\n \n return properties;\n }\n \n /**\n * Create email body content\n */\n private String createEmailBody(Delivery delivery) {\n StringBuilder body = new StringBuilder();\n \n body.append(\"Dear Customer,\\n\\n\");\n body.append(\"Please find the attached Proof of Delivery (POD) for your recent shipment.\\n\\n\");\n body.append(\"Delivery Details:\\n\");\n body.append(\"- Order Number: \").append(delivery.getTripId()).append(\"\\n\");\n body.append(\"- Shipment Number: \").append(delivery.getDocument()).append(\"\\n\");\n body.append(\"- Delivered To: \").append(delivery.getCustomerName()).append(\"\\n\");\n body.append(\"- Delivery Date: \").append(delivery.getTime().substring(0, 10)).append(\"\\n\");\n body.append(\"- Delivery Time: \").append(delivery.getTime().substring(delivery.getTime().length() - 8)).append(\"\\n\");\n body.append(\"- Driver: \").append(securityManager.getAppDriver()).append(\"\\n\");\n body.append(\"- Vehicle: \").append(securityManager.getAppVehicle()).append(\"\\n\");\n body.append(\"- Total Parcels: \").append(delivery.getNumberOfParcels()).append(\"\\n\");\n \n if (delivery.getComment() != null && !delivery.getComment().isEmpty()) {\n body.append(\"- Delivery Notes: \").append(delivery.getComment()).append(\"\\n\");\n }\n \n body.append(\"\\nThis document confirms the successful delivery of your items and includes \");\n body.append(\"digital evidence such as delivery photos and customer signatures where applicable.\\n\\n\");\n body.append(\"Thank you for your business.\\n\\n\");\n body.append(\"Best regards,\\n\");\n body.append(\"EasyDelivery Team\\n\");\n body.append(securityManager.getAppCompany());\n \n return body.toString();\n }\n \n /**\n * Generate PDF for proof of delivery\n */\n private File generatePODPdf(Delivery delivery) {\n try {\n // Use existing PDF generation logic but with secure image handling\n File pdfFile = new File(context.getCacheDir(), \"POD_\" + delivery.getDocument() + \".pdf\");\n \n // TODO: Integrate with existing PDF generation logic from SyncService\n // This would use the SecurityManager for secure image decryption\n \n Log.d(TAG, \"PDF generated: \" + pdfFile.getAbsolutePath());\n return pdfFile;\n \n } catch (Exception e) {\n Log.e(TAG, \"Failed to generate PDF\", e);\n return null;\n }\n }\n \n /**\n * Add attachment to multipart message\n */\n private void addAttachment(Multipart multipart, String filePath, String fileName) throws MessagingException {\n MimeBodyPart attachmentBodyPart = new MimeBodyPart();\n DataSource source = new FileDataSource(filePath);\n attachmentBodyPart.setDataHandler(new DataHandler(source));\n attachmentBodyPart.setFileName(fileName);\n multipart.addBodyPart(attachmentBodyPart);\n }\n \n /**\n * Test email configuration\n */\n public boolean testEmailConfiguration() {\n try {\n String username = securityManager.getEmailUsername();\n String password = securityManager.getEmailPassword();\n \n if (password == null || password.isEmpty()) {\n Log.e(TAG, \"Email configuration test failed - no password configured\");\n return false;\n }\n \n // Create test session\n Properties properties = createSecureMailProperties();\n Session session = Session.getInstance(properties, new Authenticator() {\n @Override\n protected PasswordAuthentication getPasswordAuthentication() {\n return new PasswordAuthentication(username, password);\n }\n });\n \n // Test connection\n Transport transport = session.getTransport(\"smtp\");\n transport.connect();\n transport.close();\n \n Log.d(TAG, \"Email configuration test successful\");\n return true;\n \n } catch (Exception e) {\n Log.e(TAG, \"Email configuration test failed\", e);\n return false;\n }\n }\n \n /**\n * Get email configuration status\n */\n public String getEmailStatus() {\n StringBuilder status = new StringBuilder();\n status.append(\"Username: \").append(securityManager.getEmailUsername()).append(\"\\n\");\n status.append(\"Password: \").append(securityManager.getEmailPassword() != null ? \"Configured\" : \"Not Configured\").append(\"\\n\");\n status.append(\"Recipient: \").append(securityManager.getAppEmail()).append(\"\\n\");\n \n return status.toString();\n }\n}"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"toolu_bdrk_01DBoAfMdYctesg7jjKvMygz","content":"The apply model made the following changes to the file:

